import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/glossary.md","filePath":"en/guide/glossary.md"}'),n={name:"en/guide/glossary.md"};function o(s,t,d,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p><strong>Status:</strong> Design vocabulary · Individual mechanics retain their stated status.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Skill, Technique, Familiarity and Mastery describe different kinds of progress.</li><li>Knowing an option, preparing it and successfully using it are separate steps.</li><li>Use these definitions while reading; consult the linked specs for detailed rules.</li></ul><h2 id="terms-at-a-glance" tabindex="-1">Terms at a glance <a class="header-anchor" href="#terms-at-a-glance" aria-label="Permalink to &quot;Terms at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Skill</td><td>Character capability in a broad activity; not the entire catalogue of learned options.</td></tr><tr><td>Technique</td><td>A learned option or method; having enough skill does not automatically teach every technique.</td></tr><tr><td>Familiarity</td><td>Practiced fluency with a particular action or pattern; distinct from learning it and from broad skill.</td></tr><tr><td>Mastery</td><td>Deeper expertise or specialization; not a synonym for a skill total or the Familiarity state named Mastered.</td></tr><tr><td>Special Attack (SA)</td><td>A learned martial action with its own use, commitment and cost.</td></tr><tr><td>Legacy Combat</td><td>Automatic attack cadence, retained as a supported design alternative.</td></tr><tr><td>Modern Combat</td><td>The player chooses when to begin an available action; timing does not guarantee success.</td></tr><tr><td>Flow</td><td>Sustainable combat rhythm shaped by action choice, exertion and recovery.</td></tr><tr><td>Core Pattern</td><td>The learned structure of a spell; variants can modify it without erasing its identity.</td></tr><tr><td>Active Memory</td><td>The selection of learned spell patterns prepared for immediate access to normal casting, not instant casting.</td></tr><tr><td>Concentration</td><td>Stability under pressure while casting or sustaining suitable mental work; not automatically another skillcap cost.</td></tr><tr><td>Local Trauma</td><td>Structural harm to a body region, distinct from global health damage.</td></tr><tr><td>Global Hits</td><td>Overall health, which coexists with local body-region condition.</td></tr><tr><td>Masterwork</td><td>A rare craft achievement within the quality proposal; not automatically a magical item.</td></tr><tr><td>Latent Property</td><td>A possible hidden potential revealed through suitable use or discovery; not guaranteed on every good item.</td></tr><tr><td>Profession Path</td><td>A specialization within a profession, expressed through knowledge and techniques rather than a mandatory separate skill.</td></tr><tr><td>Prepared Repertoire</td><td>The martial options selected for ready access; separate from magical Active Memory and not a mandatory INT investment.</td></tr></tbody></table><h2 id="what-s-new-in-syrolands" tabindex="-1">What&#39;s new in Syrolands <a class="header-anchor" href="#what-s-new-in-syrolands" aria-label="Permalink to &quot;What&#39;s new in Syrolands&quot;">​</a></h2><p>These terms connect character capability, player decisions and learned knowledge across systems. Some names are familiar from UO, but Syrolands definitions govern this guide; Mastery does not automatically mean UO&#39;s later Skill Masteries system.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You learn a Technique, improve its Familiarity through practice and choose it for your Prepared Repertoire. Your Skill still matters when you attempt it; having it ready does not guarantee a hit.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/introduction.html">Introduction</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/">Design Specs: all systems and detailed definitions</a></p>',14)])])}const p=e(n,[["render",o]]);export{u as __pageData,p as default};
